for s in S:
 n=s['number'];r={k:s[k]for k in ['code_id','source_id','source_sha256','number']};r.update(status='rewrite_draft',proposed_xml=B[n],proposed_sha256=sha(B[n]),reason=R[n][0],benefit_review=R[n][1],current_beforeimage_sha256=s['current_beforeimage_sha256'],source_body_sha256=sha(s['source_xml']),source_notes_sha256=sha(s['source_notes_xml']),review_notes='Corps canonique entier, notes et renvois utiles lus ; aucune proposition existante lors de la capture. Complément indispensable du paquet47 : trois articulations CAE/CIE, accès législatif GUSO et notification adultes-relais. Le contrat unique est sans terme ; les périodes de formation, mission et aide sont distinctes. Les anciens termes et créances restent protégés par L1241-1 transitoire du paquet70. Aucun taux d’aide, critère d’emploi nouveau ou financement chiffré n’est inventé ; les conditions autonomes d’aide restent applicables. Noyau de rupture non modifié. Aucune inscription ni publication par cet auteur.')
 if n in ['L7122-23','L5134-105']:r.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=['Supprime les secondes adhésions et déclarations identiques dues au seul changement de support CDD.'if n=='L7122-23'else'Supprime le cumul d’une notification annuelle spéciale avec la procédure commune des nouveaux contrats uniques.'])
 A.append(r)
